{"code": "import pytest
import impl


class TestBasicAuthorization:
    """Test core ALLOW/DENY decisions."""

    def test_simple_allow(self):
        """ALLOW when policy matches."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_simple_deny(self):
        """DENY when policy matches."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "DENY", "principal": "*", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "DENY"

    def test_no_matching_policy_defaults_deny(self):
        """No matching policy returns DENY (default-deny)."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "user:bob", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "DENY"

    def test_empty_policies_defaults_deny(self):
        """Empty policies list returns DENY."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        assert impl.authorize(request, []) == "DENY"


class TestDenyOverride:
    """Test XACML deny-override rule (any DENY overrides ALLOW)."""

    def test_deny_overrides_allow(self):
        """DENY overrides ALLOW regardless of order."""
        request = {"subject": "alice", "roles": ["contractor"], "action": "read", "resource": "docs/reports/Q1"}
        policies = [
            {"effect": "ALLOW", "principal": "user:alice", "action": "*", "resource": "*"},
            {"effect": "DENY", "principal": "role:contractor", "action": "read", "resource": "docs/reports/*"}
        ]
        assert impl.authorize(request, policies) == "DENY"

    def test_deny_overrides_even_if_later(self):
        """DENY overrides even when appearing after ALLOW."""
        request = {"subject": "alice", "roles": ["contractor"], "action": "read", "resource": "docs/reports/Q1"}
        policies = [
            {"effect": "DENY", "principal": "role:contractor", "action": "read", "resource": "docs/reports/*"},
            {"effect": "ALLOW", "principal": "user:alice", "action": "*", "resource": "*"}
        ]
        assert impl.authorize(request, policies) == "DENY"

    def test_multiple_allows_without_deny_returns_allow(self):
        """Multiple ALLOWs with no DENY returns ALLOW."""
        request = {"subject": "alice", "roles": ["admin"], "action": "read", "resource": "file"}
        policies = [
            {"effect": "ALLOW", "principal": "user:alice", "action": "read", "resource": "file"},
            {"effect": "ALLOW", "principal": "role:admin", "action": "*", "resource": "*"}
        ]
        assert impl.authorize(request, policies) == "ALLOW"


class TestPrincipalMatching:
    """Test principal matching rules."""

    def test_principal_wildcard_matches_all(self):
        """Principal '*' matches any subject/roles."""
        request = {"subject": "anyone", "roles": ["any_role"], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_principal_user_exact_match(self):
        """Principal 'user:X' matches when subject == X exactly."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_principal_user_no_match_different_subject(self):
        """Principal 'user:X' doesn't match different subject."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "user:bob", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "DENY"

    def test_principal_role_in_list(self):
        """Principal 'role:X' matches when X in request.roles."""
        request = {"subject": "alice", "roles": ["admin", "user"], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "role:admin", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_principal_role_not_in_list(self):
        """Principal 'role:X' doesn't match when X not in request.roles."""
        request = {"subject": "alice", "roles": ["user"], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "role:admin", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "DENY"

    def test_principal_user_prefix_is_literal_not_pattern(self):
        """Principal 'user:al*' is literal, not a glob pattern."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "user:al*", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "DENY"


class TestPatternMatching:
    """Test action and resource pattern matching with wildcards."""

    def test_trailing_wildcard_is_prefix_match(self):
        """Pattern 's3:Get*' matches 's3:GetObject' (prefix match)."""
        request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:Get*", "resource": "bucket"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_trailing_wildcard_matches_empty_suffix(self):
        """Pattern 's3:Get*' matches 's3:Get' (empty suffix)."""
        request = {"subject": "alice", "roles": [], "action": "s3:Get", "resource": "bucket"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:Get*", "resource": "bucket"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_bare_wildcard_matches_anything(self):
        """Bare '*' matches any action/resource."""
        request = {"subject": "alice", "roles": [], "action": "anything", "resource": "anything_else"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "*", "resource": "*"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_non_final_wildcard_is_literal(self):
        """Non-final '*' is literal: 's3:*Object' is exact match only."""
        request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "bucket"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:*Object", "resource": "bucket"}]
        assert impl.authorize(request, policies) == "DENY"

    def test_non_final_wildcard_exact_match(self):
        """Pattern 's3:*Object' matches exactly 's3:*Object'."""
        request = {"subject": "alice", "roles": [], "action": "s3:*Object", "resource": "bucket"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:*Object", "resource": "bucket"}]
        assert impl.authorize(request, policies) == "ALLOW"

    def test_prefix_wildcard_does_not_glob(self):
        """Pattern 'docs/reports/*' doesn't match 'docs/reportsQ1' (prefix only)."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "docs/reportsQ1"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "read", "resource": "docs/reports/*"}]
        assert impl.authorize(request, policies) == "DENY"

    def test_pattern_matching_case_sensitive(self):
        """Pattern matching is case-sensitive."""
        request = {"subject": "alice", "roles": [], "action": "Read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "DENY"

    def test_exact_match_required_without_wildcard(self):
        """Exact match required when pattern has no wildcard."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file.txt"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "read", "resource": "file"}]
        assert impl.authorize(request, policies) == "DENY"


class TestValidation:
    """Test request and policy validation."""

    def test_missing_request_field_subject(self):
        """ValueError when request missing 'subject'."""
        request = {"roles": [], "action": "read", "resource": "file"}
        with pytest.raises(ValueError, match="subject"):
            impl.authorize(request, [])

    def test_missing_request_field_roles(self):
        """ValueError when request missing 'roles'."""
        request = {"subject": "alice", "action": "read", "resource": "file"}
        with pytest.raises(ValueError, match="roles"):
            impl.authorize(request, [])

    def test_missing_request_field_action(self):
        """ValueError when request missing 'action'."""
        request = {"subject": "alice", "roles": [], "resource": "file"}
        with pytest.raises(ValueError, match="action"):
            impl.authorize(request, [])

    def test_missing_request_field_resource(self):
        """ValueError when request missing 'resource'."""
        request = {"subject": "alice", "roles": [], "action": "read"}
        with pytest.raises(ValueError, match="resource"):
            impl.authorize(request, [])

    def test_request_roles_not_list(self):
        """ValueError when request.roles is not a list."""
        request = {"subject": "alice", "roles": "admin", "action": "read", "resource": "file"}
        with pytest.raises(ValueError, match="roles.*list"):
            impl.authorize(request, [])

    def test_missing_policy_field_effect(self):
        """ValueError when policy missing 'effect'."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"principal": "*", "action": "read", "resource": "file"}]
        with pytest.raises(ValueError, match="effect"):
            impl.authorize(request, policies)

    def test_missing_policy_field_principal(self):
        """ValueError when policy missing 'principal'."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "action": "read", "resource": "file"}]
        with pytest.raises(ValueError, match="principal"):
            impl.authorize(request, policies)

    def test_missing_policy_field_action(self):
        """ValueError when policy missing 'action'."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "*", "resource": "file"}]
        with pytest.raises(ValueError, match="action"):
            impl.authorize(request, policies)

    def test_missing_policy_field_resource(self):
        """ValueError when policy missing 'resource'."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "ALLOW", "principal": "*", "action": "read"}]
        with pytest.raises(ValueError, match="resource"):
            impl.authorize(request, policies)

    def test_invalid_effect_allow_lowercase(self):
        """ValueError when policy.effect is 'Allow' (not 'ALLOW')."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "Allow", "principal": "*", "action": "read", "resource": "file"}]
        with pytest.raises(ValueError, match="Allow"):
            impl.authorize(request, policies)

    def test_invalid_effect_permit(self):
        """ValueError when policy.effect is 'PERMIT'."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [{"effect": "PERMIT", "principal": "*", "action": "read", "resource": "file"}]
        with pytest.raises(ValueError, match="PERMIT"):
            impl.authorize(request, policies)

    def test_validation_before_decision(self):
        """All policies validated before any decision."""
        request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
        policies = [
            {"effect": "ALLOW", "principal": "*", "action": "read", "resource": "file"},
            {"effect": "INVALID", "principal": "*", "action": "read", "resource": "file"}
        ]
        with pytest.raises(ValueError, match="INVALID"):
            impl.authorize(request, policies)
"}
